function isBalanced(s) {
  const stack = [];
  const closerFor = { ')': '(', ']': '[', '}': '{' };

  for (const ch of s) {
    if (ch === '(' || ch === '[' || ch === '{') {
      stack.push(ch);
    } else if (ch in closerFor) {
      if (stack.pop() !== closerFor[ch]) return false;
    }
  }
  return stack.length === 0;
}

console.log(isBalanced('a(b[c]{d})e'));  // true
console.log(isBalanced('([)]'));         // false

