function makeQueue(capacity) {
  return { buf: new Array(capacity), head: 0, tail: 0, size: 0, capacity };
}

function enqueue(q, value) {
  if (q.size === q.capacity) return false;   // full
  q.buf[q.tail] = value;
  q.tail = (q.tail + 1) % q.capacity;
  q.size++;
  return true;
}

function dequeue(q) {
  if (q.size === 0) return null;             // empty
  const value = q.buf[q.head];
  q.head = (q.head + 1) % q.capacity;
  q.size--;
  return value;
}

