function firstUnique(s) {
  const count = Object.create(null);
  for (const c of s) count[c] = (count[c] || 0) + 1;
  const q = [];
  for (const c of s) q.push(c);
  while (q.length > 0 && count[q[0]] > 1) q.shift();
  return q.length > 0 ? q[0] : null;
}

