function twoStackQueue(ops) {
  const inbox = [], outbox = [], out = [];
  for (const op of ops) {
    if (op === 'pop') {
      if (outbox.length === 0) {
        while (inbox.length > 0) outbox.push(inbox.pop());
      }
      out.push(outbox.length > 0 ? outbox.pop() : null);
    } else {
      inbox.push(Number(op.slice(5)));
    }
  }
  return out;
}

